def solve(tasks, n):
    if not tasks:
        return 0
    counts = {}
    for t in tasks:
        counts[t] = counts.get(t, 0) + 1
    m = max(counts.values())
    k = sum(1 for v in counts.values() if v == m)
    return max(len(tasks), (m - 1) * (n + 1) + k)

