        return 0
    nodes = [None if v is None else [v, None, None] for v in tree]
    root = nodes[0]
    queue = [root]
    qi = 0
    i = 1
    while qi < len(queue) and i < len(nodes):
        cur = queue[qi]
        qi += 1
        if i < len(nodes):
            cur[1] = nodes[i]
            if nodes[i] is not None:
                queue.append(nodes[i])
            i += 1
        if i < len(nodes):
            cur[2] = nodes[i]
            if nodes[i] is not None:
                queue.append(nodes[i])
            i += 1
    best = [float('-inf')]
    def gain(node):
        if node is None:
            return 0
        left = max(gain(node[1]), 0)
        right = max(gain(node[2]), 0)
        best[0] = max(best[0], node[0] + left + right)
        return node[0] + max(left, right)
    gain(root)
    return best[0]
